function initCookies() {
  const banner = document.querySelector('[data-cookies]');
  if (!banner) return;

  let cookiesValue = null;
  try {
    cookiesValue = localStorage.getItem('cookies');
  } catch (e) {}

  if (cookiesValue) {
    banner.remove();
    return;
  }

  gsap.fromTo(banner, { yPercent: 100 }, {
    yPercent: 0,
    duration: durM,
    delay: delayReveal,
    ease: 'Out'
  });

  function dismiss(value) {
    try {
      localStorage.setItem('cookies', value);
    } catch (e) {}
    gsap.to(banner, {
      yPercent: 100,
      duration: durM,
      ease: 'In',
      onComplete: () => banner.remove()
    });
  }

  document.querySelector('[data-cookies="accept"]').addEventListener('click', () => dismiss(
    'accepted'));
  document.querySelector('[data-cookies="decline"]').addEventListener('click', () => dismiss(
    'declined'));
}

function initThemeChange() {
  const themedElements = document.querySelectorAll('[data-theme]');
  if (!themedElements.length) return;

  function createTrigger(section, addClass, removeClass) {
    if (getComputedStyle(section).display === 'none') return;

    const sectionRect = section.getBoundingClientRect();

    themedElements.forEach(el => {
      const elRect = el.getBoundingClientRect();
      const elCenterX = elRect.left + elRect.width / 2;

      if (elCenterX < sectionRect.left || elCenterX > sectionRect.right) return;

      ScrollTrigger.create({
        trigger: section,
        start: () => `top top+=${elRect.top + elRect.height / 2}`,
        end: () => `bottom top+=${elRect.top + elRect.height / 2}`,
        markers: false,

        onEnter: () => {
          el.classList.add(addClass);
          el.classList.remove(...removeClass);
        },

        onEnterBack: () => {
          el.classList.add(addClass);
          el.classList.remove(...removeClass);
        }
      });
    });
  }

  document.querySelectorAll('[data-bg="color"]').forEach(section => {
    createTrigger(section, 'theme_on-color', ['theme_on-light', 'theme_on-dark']);
  });

  document.querySelectorAll('[data-bg="light"]').forEach(section => {
    createTrigger(section, 'theme_on-light', ['theme_on-dark', 'theme_on-color']);
  });

  document.querySelectorAll('[data-bg="dark"]').forEach(section => {
    createTrigger(section, 'theme_on-dark', ['theme_on-light', 'theme_on-color']);
  });
}

function initSnapSections() {
  gsap.matchMedia().add(`(min-width: ${breakPoint}px)`, () => {

    const sections = gsap.utils.toArray('[data-snap]');
    if (!sections.length || !lenis) return;

    let snapTimeout = null;

    lenis.on('scroll', () => {
      clearTimeout(snapTimeout);
      snapTimeout = setTimeout(() => {
        const vh = window.innerHeight;
        let bestSection = null;
        let bestRatio = 0;

        sections.forEach(section => {
          const rect = section.getBoundingClientRect();
          const visible = Math.min(rect.bottom, vh) - Math.max(rect.top, 0);
          const ratio = visible / Math.min(section.offsetHeight, vh);

          if (ratio > 0.5 && ratio > bestRatio) {
            bestRatio = ratio;
            bestSection = section;
          }
        });

        if (bestSection) {
          lenis.scrollTo(bestSection, {
            duration: durL,
            easing: gsap.parseEase('Ease')
          });
        }
      }, 40);
    });

  });
}

function initForm() {
  // Form button
  document.querySelectorAll('[data-form-btn]').forEach(btn => {
    btn.addEventListener('click', e => {
      e.preventDefault()
      const form = btn.closest('form')
      if (!form) return

      const textElements = btn.querySelectorAll('[hover="text"]')

      const handleSubmit = () => {
        textElements.forEach(element => {
          element.textContent = 'Sending...'
        })
      }

      form.addEventListener('submit', handleSubmit, { once: true })
      form.requestSubmit()
    })
  })

  // Input label focus in/out
  document.querySelectorAll('.input_field').forEach(field => {
    const label = field.parentElement.querySelector('.input_label');
    if (!label) return;

    field.addEventListener('focusin', () => label.classList.add('focused'));
    field.addEventListener('focusout', () => {
      if (!field.value.trim()) label.classList.remove('focused');
    });
  });

  document.querySelectorAll('input[type="tel"]').forEach(input => {
    input.addEventListener('input', () => {
      input.value = input.value.replace(/[^\d+\-]/g, '');
    });
  });

  document.querySelectorAll('input[name="Name"]').forEach(input => {
    input.addEventListener('input', () => {
      input.value = input.value.replace(/[\d!@#$%^&*()_+=\[\]{};:'"\\|,.<>/?~`]/g, '');
    });
  });
}

function initUtmFields() {
  const titleInput = document.querySelector('input[name="title"]');
  if (titleInput) titleInput.value = 'Deal from Era';

  const urlParams = new URLSearchParams(window.location.search);

  const fields = {
    utm_source: urlParams.get('utm_source') || '',
    utm_medium: urlParams.get('utm_medium') || '',
    utm_campaign: urlParams.get('utm_campaign') || '',
    utm_content: urlParams.get('utm_content') || '',
    utm_url: urlParams.get('utm_url') || '',
    page_url: window.location.href
  };

  Object.entries(fields).forEach(([key, value]) => {
    const input = document.querySelector(`input[name="${key}"]`);
    if (input) input.value = value;
  });
}

function initPlayPauseVideoScroll() {
  const wrappers = gsap.utils.toArray('[data-video-playpause]');

  wrappers.forEach(el => {
    const videos = el.querySelectorAll('.video');
    if (!videos.length) return;

    videos.forEach(video => {
      video.load();
      video.currentTime = 0;
    });

    ScrollTrigger.create({
      trigger: el,
      start: 'top bottom',
      end: 'bottom top',
      onEnter: () => videos.forEach(v => v.play().catch(() => {})),
      onEnterBack: () => videos.forEach(v => v.play().catch(() => {})),
      onLeave: () => videos.forEach(v => v.pause()),
      onLeaveBack: () => videos.forEach(v => v.pause()),
    });
  });
}

// Utilities

function animateTextA(selector, direction, delay) {
  const elements = gsap.utils.toArray(selector);

  if (!elements.length) return;

  elements.forEach((element, elementIndex) => {
    if (!element.textContent.trim()) return;

    if (!element._split) {
      element._split = new SplitText(element, {
        type: 'chars',
        tag: 'span',
        charsClass: 'split-char',
        smartWrap: true
      });
    }

    const elementDelay = (elementIndex * stagger * 1);

    switch (direction) {
    case 'reveal':
      gsap.fromTo(element._split.chars, {
        opacity: 0,
        rotateX: 90,
        x: '10rem',
        transformOrigin: 'center bottom',
      }, {
        opacity: 1,
        rotateX: 0,
        x: '0rem',
        duration: durL,
        delay: (delay ?? delayReveal) + elementDelay,
        stagger: stagger,
        ease: 'Out',
        overwrite: true
      });
      break;

    case 'hide':
      gsap.to(element._split.chars, {
        opacity: 0,
        rotateX: -90,
        x: '-10rem',
        transformOrigin: 'center top',
        duration: durS,
        delay: delay ?? 0,
        stagger: stagger * 0.5,
        ease: 'In',
        overwrite: true
      });
      break;

    case 'initial':
      gsap.set(element._split.chars, {
        opacity: 0,
        rotateX: -90,
        x: '-10rem',
        transformOrigin: 'center top'
      });
      break;
    }
  });
}

