function initAllParallax() {
  // Images parallax
  gsap.utils.toArray('[data-parallax="img"]').forEach((img) => {
    const wrapper = img.closest('[data-parallax="w"]');
    if (!wrapper) return;

    const isMobile = window.innerWidth < breakPoint;
    if (isMobile && wrapper.dataset.mob === 'off') return;
    if (!isMobile && wrapper.dataset.desk === 'off') return;

    gsap.fromTo(img, { yPercent: -15, translateZ: 10 }, {
      yPercent: 15,
      translateZ: 10,
      ease: 'none',
      scrollTrigger: {
        trigger: wrapper,
        start: 'top bottom',
        scrub: 0.5
      }
    });
  });

  // Images out parallax
  gsap.utils.toArray('[data-parallax="img-out"]').forEach((img) => {
    const wrapper = img.closest('[data-parallax="w"]');
    if (!wrapper) return;

    const isMobile = window.innerWidth < breakPoint;
    if (isMobile && wrapper.dataset.mob === 'off') return;
    if (!isMobile && wrapper.dataset.desk === 'off') return;

    gsap.fromTo(img, { yPercent: 0, translateZ: 10 }, {
      yPercent: 20,
      translateZ: 10,
      ease: 'none',
      scrollTrigger: {
        trigger: wrapper,
        start: 'bottom bottom',
        end: 'bottom top',
        scrub: 0.5
      }
    });
  });

  // Images in parallax
  gsap.utils.toArray('[data-parallax="img-in"]').forEach((img) => {
    const wrapper = img.closest('[data-parallax="w"]');
    if (!wrapper) return;

    const isMobile = window.innerWidth < breakPoint;
    if (isMobile && wrapper.dataset.mob === 'off') return;
    if (!isMobile && wrapper.dataset.desk === 'off') return;

    gsap.fromTo(img, { yPercent: -20, translateZ: 10 }, {
      yPercent: 0,
      translateZ: 10,
      ease: 'none',
      scrollTrigger: {
        trigger: wrapper,
        start: 'top bottom',
        end: 'bottom bottom',
        scrub: true
      }
    });
  });

  // Ctn down parallax
  gsap.utils.toArray('[data-parallax="ctn-down"]').forEach((ctn) => {
    if (!ctn) return;

    const isMobile = window.innerWidth < breakPoint;
    if (isMobile && ctn.dataset.mob === 'off') return;
    if (!isMobile && ctn.dataset.desk === 'off') return;

    gsap.fromTo(ctn, { yPercent: -10 }, {
      yPercent: 10,
      ease: 'none',
      scrollTrigger: {
        trigger: ctn,
        start: 'top 125%',
        end: 'bottom -25%',
        scrub: 0.5
      }
    });
  });

  // Ctn up parallax
  gsap.utils.toArray('[data-parallax="ctn-up"]').forEach((ctn) => {
    if (!ctn) return;

    const isMobile = window.innerWidth < breakPoint;
    if (isMobile && ctn.dataset.mob === 'off') return;
    if (!isMobile && ctn.dataset.desk === 'off') return;

    gsap.fromTo(ctn, { yPercent: 10 }, {
      yPercent: -10,
      ease: 'none',
      scrollTrigger: {
        trigger: ctn,
        start: 'top 125%',
        end: 'bottom -25%',
        scrub: 0.5
      }
    });
  });
}

function initScrollElementsReveal() {

  function createRevealTrigger(trigger, items, animateFn) {
    const horizontalArea = trigger.closest('[data-scroll-horizontal]');

    ScrollTrigger.create({
      trigger,
      containerAnimation: horizontalArea?._horizontalTween,
      start: horizontalArea ? 'left bottom' : 'top bottom',
      once: true,
      onEnter: () => animateFn(items, 'reveal')
    });
  }

  // Accent reveal animation
  const accents = document.querySelectorAll('[data-scroll-reveal="a"]');

  if (accents.length) {
    const groups = new Map();

    accents.forEach(accent => {
      const wrapper = accent.closest('[data-scroll-reveal="w"]');
      const key = wrapper || accent;

      if (!groups.has(key)) groups.set(key, { trigger: key, items: [] });
      groups.get(key).items.push(accent);
    });

    groups.forEach(({ trigger, items }) => {
      gsap.set(items, { visibility: 'visible' });
      createRevealTrigger(trigger, items, animateTextA);
      animateTextA(items, 'initial');
    });
  }

  // Headlines reveal animation
  const headlines = document.querySelectorAll('[data-scroll-reveal="h"]');

  if (headlines.length) {
    const groups = new Map();

    headlines.forEach(headline => {
      const wrapper = headline.closest('[data-scroll-reveal="w"]');
      const key = wrapper || headline;

      if (!groups.has(key)) groups.set(key, { trigger: key, items: [] });
      groups.get(key).items.push(headline);
    });

    groups.forEach(({ trigger, items }) => {
      gsap.set(items, { visibility: 'visible' });
      createRevealTrigger(trigger, items, animateTextH);
      animateTextH(items, 'initial');
    });
  }

  // Paragraphs reveal animation
  const paragraphs = document.querySelectorAll('[data-scroll-reveal="p"]');

  if (paragraphs.length) {
    const groups = new Map();

    paragraphs.forEach(paragraph => {
      const wrapper = paragraph.closest('[data-scroll-reveal="w"]');
      const key = wrapper || paragraph;

      if (!groups.has(key)) groups.set(key, { trigger: key, items: [] });
      groups.get(key).items.push(paragraph);
    });

    groups.forEach(({ trigger, items }) => {
      gsap.set(items, { visibility: 'visible' });
      createRevealTrigger(trigger, items, animateTextP);
      animateTextP(items, 'initial');
    });
  }

  // Ctns reveal animation
  const containers = document.querySelectorAll('[data-scroll-reveal="ctn"]');

  if (containers.length) {
    const groups = new Map();

    containers.forEach(container => {
      const wrapper = container.closest('[data-scroll-reveal="w"]');
      const key = wrapper || container;

      if (!groups.has(key)) groups.set(key, { trigger: key, items: [] });
      groups.get(key).items.push(container);
    });

    groups.forEach(({ trigger, items }) => {
      gsap.set(items, { visibility: 'visible' });
      createRevealTrigger(trigger, items, animateCtn);
      animateCtn(items, 'initial');
    });
  }

  // Lines reveal animation
  const lines = document.querySelectorAll('[data-scroll-reveal="line"]');

  if (lines.length) {
    const groups = new Map();

    lines.forEach(line => {
      const wrapper = line.closest('[data-scroll-reveal="w"]');
      const key = wrapper || line;

      if (!groups.has(key)) groups.set(key, { trigger: key, items: [] });
      groups.get(key).items.push(line);
    });

    groups.forEach(({ trigger, items }) => {
      gsap.set(items, { visibility: 'visible' });
      createRevealTrigger(trigger, items, animateLine);
      animateLine(items, 'initial');
    });
  }

  // Slide reveal animation
  const slides = document.querySelectorAll('[data-scroll-reveal="slide"]');

  if (slides.length) {
    const groups = new Map();

    slides.forEach(slide => {
      const wrapper = slide.closest('[data-scroll-reveal="w"]');
      const key = wrapper || slide;

      if (!groups.has(key)) groups.set(key, { trigger: key, items: [] });
      groups.get(key).items.push(slide);
    });

    groups.forEach(({ trigger, items }) => {
      gsap.set(items, { visibility: 'visible' });
      createRevealTrigger(trigger, items, animateSlide);
      animateSlide(items, 'initial');
    });
  }
}

function initMagneticEffect() {
  gsap.matchMedia().add(`(min-width: ${breakPoint}px)`, () => {

    const magnets = document.querySelectorAll('[data-magnetic-btn]');

    const resetEl = (el, immediate) => {
      gsap.killTweensOf(el);
      (immediate ? gsap.set : gsap.to)(el, {
        x: 0,
        y: 0,
        force3D: true,
        clearProps: 'all',
        ...(!immediate && { ease: 'elastic.out(1, 0.3)', duration: 1.6 })
      });
    };

    const getInners = m => m.querySelectorAll('[data-magnetic-inner]');

    const onEnter = e => {
      const m = e.currentTarget;
      resetEl(m, true);
      getInners(m).forEach(inner => resetEl(inner, true));
    };

    const onMove = e => {
      const m = e.currentTarget;
      const b = m.getBoundingClientRect();
      const strength = parseFloat(m.dataset.magneticStrength) || 25;
      const innerStrength = parseFloat(m.dataset.magneticStrengthInner) || strength;
      const offsetX = ((e.clientX - b.left) / m.offsetWidth - 0.5) * (strength / 16);
      const offsetY = ((e.clientY - b.top) / m.offsetHeight - 0.5) * (strength / 16);

      gsap.to(m, {
        x: offsetX + 'em',
        y: offsetY + 'em',
        force3D: true,
        ease: 'power4.out',
        duration: 1.6
      });

      getInners(m).forEach(inner => {
        gsap.to(inner, {
          x: ((e.clientX - b.left) / m.offsetWidth - 0.5) * (innerStrength / 16) +
            'em',
          y: ((e.clientY - b.top) / m.offsetHeight - 0.5) * (innerStrength / 16) +
            'em',
          force3D: true,
          ease: 'power4.out',
          duration: 2
        });
      });
    };

    const onLeave = e => {
      const m = e.currentTarget;
      resetEl(m, false);
      getInners(m).forEach(inner => resetEl(inner, false));
    };

    magnets.forEach(m => {
      m.addEventListener('mouseenter', onEnter);
      m.addEventListener('mousemove', onMove);
      m.addEventListener('mouseleave', onLeave);
    });

  });
}

// Components

function initNavItemHover() {
  function xPositionStagger(maxDelay) {
    return (i, target, targets) => {
      const lefts = targets.map(t => t.getBoundingClientRect().left);
      const min = Math.min(...lefts);
      const max = Math.max(...lefts);
      const range = max - min || 1;
      return (lefts[i] - min) / range * maxDelay;
    };
  }

  document.querySelectorAll('[hover-nav-item]').forEach(item => {
    const texts = item.querySelectorAll("[hover='text']");
    if (texts.length < 2) return;

    const text1 = new SplitText(texts[0], {
      type: 'words,chars',
      tag: 'span',
      smartWrap: true,
      wordsClass: 'split-word',
      charsClass: 'split-char',
      mask: 'words'
    });
    const text2 = new SplitText(texts[1], {
      type: 'words,chars',
      tag: 'span',
      smartWrap: true,
      wordsClass: 'split-word',
      charsClass: 'split-char',
      mask: 'words'
    });

    gsap.set(text2.chars, { yPercent: 100, opacity: 0 });

    function playForward() {
      gsap.fromTo(text1.chars, {
        opacity: 1,
        yPercent: 0,
      }, {
        opacity: 0,
        yPercent: -100,
        duration: durM,
        ease: 'Ease',
        stagger: xPositionStagger(stagger * 2),
        overwrite: true,
        force3D: true
      });

      gsap.fromTo(text2.chars, {
        yPercent: 100,
        opacity: 0,
      }, {
        opacity: 1,
        yPercent: 0,
        duration: durM,
        ease: 'Ease',
        stagger: xPositionStagger(stagger * 2),
        overwrite: true,
        force3D: true
      });
    }

    function playReverse() {
      gsap.to(text1.chars, {
        opacity: 1,
        yPercent: 0,

        duration: durM,
        ease: 'Ease',
        stagger: xPositionStagger(stagger * 2),
        overwrite: true,
        force3D: true
      });

      gsap.to(text2.chars, {
        opacity: 0,
        yPercent: 100,

        duration: durM,
        ease: 'Ease',
        stagger: xPositionStagger(stagger * 2),
        overwrite: true,
        force3D: true
      });
    }

    const trigger = item.closest('[hover-nav-item-trigger]') || item;

    trigger.addEventListener('mouseenter', playForward);
    trigger.addEventListener('mouseleave', playReverse);
  });
}

function initLinkHover() {
  document.querySelectorAll('[hover-link]').forEach(item => {
    const texts = item.querySelectorAll("[hover='text']");
    if (texts.length < 2) return;

    const text1 = new SplitText(texts[0], {
      type: 'lines,words,chars',
      tag: 'span',
      linesClass: 'split-line',
      wordsClass: 'split-word',
      charsClass: 'split-char',
      smartWrap: true
    });
    const text2 = new SplitText(texts[1], {
      type: 'words,chars',
      tag: 'span',
      wordsClass: 'split-word',
      charsClass: 'split-char',
      smartWrap: true
    });

    const lines = text1.lines.map(line => {
      const u = document.createElement('span');
      u.classList.add('link_line');
      line.appendChild(u);
      return u;
    });

    gsap.set(lines, { scaleX: 1, transformOrigin: 'right center' });
    gsap.set(text2.chars, { opacity: 0, x: '-0.4em', yPercent: 25, rotateY: 90 });

    function playForward() {
      gsap.fromTo(text1.chars, {
        opacity: 1,
        x: '0em',
        yPercent: 0,
        rotateY: 0
      }, {
        opacity: 0,
        x: '0.4em',
        yPercent: -25,
        rotateY: -90,
        duration: durM,
        ease: 'Out',
        stagger: stagger / 4,
        overwrite: true,
        force3D: true
      });

      gsap.fromTo(text2.chars, {
        opacity: 0,
        x: '-0.4em',
        yPercent: 25,
        rotateY: 90
      }, {
        opacity: 1,
        x: '0em',
        yPercent: 0,
        rotateY: 0,
        duration: durM,
        ease: 'Out',
        delay: 0.2,
        stagger: stagger / 4,
        overwrite: true,
        force3D: true
      });

      gsap.fromTo(lines, {
        scaleX: 1,
        transformOrigin: 'right center'
      }, {
        scaleX: 0,
        duration: durM,
        ease: 'Out',
        stagger: stagger,
        overwrite: true
      });
    }

    function playReverse() {
      gsap.to(text1.chars, {
        opacity: 1,
        x: '0em',
        yPercent: 0,
        rotateY: 0,
        duration: durM,
        ease: 'Out',
        delay: 0.2,
        stagger: stagger / 4,
        overwrite: true,
        force3D: true
      });

      gsap.to(text2.chars, {
        opacity: 0,
        x: '-0.4em',
        yPercent: 25,
        rotateY: 90,
        duration: durM,
        ease: 'Out',
        stagger: stagger / 4,
        overwrite: true,
        force3D: true
      });

      gsap.to(lines, {
        scaleX: 1,
        transformOrigin: 'left center',
        duration: durM,
        ease: 'Out',
        stagger: stagger,
        overwrite: true
      });
    }

    const trigger = item.closest('[hover-link-trigger]') || item;

    trigger.addEventListener("mouseenter", playForward);
    trigger.addEventListener("mouseleave", playReverse);
  });
}

function initBtnCircleHover() {
  document.querySelectorAll('[hover-btn-circle]').forEach(btn => {
    const arcs = btn.querySelectorAll('[data-arc]');
    if (!arcs.length) return;

    const circumference = 2 * Math.PI * 103.5;
    const arcLength = circumference * 0.0417;

    gsap.set(arcs, { strokeDasharray: `${arcLength} ${circumference}` });

    const tl = gsap.timeline({ paused: true })
      .to(arcs, {
        strokeDasharray: `${circumference / 2} ${circumference}`,
        duration: durM,
        ease: 'InOut'
      });

    btn.addEventListener('mouseenter', () => tl.play());
    btn.addEventListener('mouseleave', () => tl.reverse());
  });
}

function initSelect() {
  document.querySelectorAll('[data-select=""]').forEach(dropdown => {
    const trigger = dropdown.querySelector('[data-select="btn"]');
    const values = dropdown.querySelectorAll('[data-select="value"]');
    const items = dropdown.querySelectorAll('[data-select="item"]');
    const defaultText = values[0]?.textContent;

    function updateValue() {
      const active = [...items].filter(i => i.classList.contains('is-active'));
      let text;

      if (!active.length) {
        text = defaultText;
      } else if (active.length === 1) {
        text = active[0].textContent.trim();
      } else {
        text = `${active[0].textContent.trim()} +${active.length - 1}`;
      }

      values.forEach(value => value.textContent = text);
    }

    trigger.addEventListener('click', () => {
      dropdown.classList.toggle('is-open');
    });

    items.forEach(item => {
      item.addEventListener('click', () => {
        dropdown.classList.remove('is-open');
        requestAnimationFrame(updateValue);
      });
    });

    document.addEventListener('click', e => {
      if (!dropdown.contains(e.target)) dropdown.classList.remove('is-open');
    });

    updateValue();
  });
}

function initPins() {
  const pins = document.querySelectorAll('[data-pin]');
  if (!pins.length) return;

  pins.forEach(pin => {
    const plusV = pin.querySelector(`[data-ico-plus="v"]`);
    const pulses = pin.querySelectorAll(`[data-pin-pulse]`);
    const pinW = pin.offsetWidth;

    if (pulses.length) {
      gsap.fromTo(pulses, { opacity: 1, width: pinW, height: pinW }, {
        opacity: 0,
        width: pinW * 1.6,
        height: pinW * 1.6,
        duration: durL,
        ease: 'In',
        stagger: 0.2,
        repeat: -1,
      });
    }

    if (plusV) {
      function playForward() {
        gsap.fromTo(plusV, { rotate: 0 }, {
          rotate: -90,
          duration: durM,
          ease: 'Out',
          overwrite: true
        })
      }

      function playReverse() {
        gsap.to(plusV, {
          rotate: -180,
          duration: durM,
          ease: 'Out',
          overwrite: true
        })
      }

      pin.addEventListener("mouseenter", playForward);
      pin.addEventListener("mouseleave", playReverse);
    }
  });
}

function initLogo() {
  const logo = document.querySelector('.header-logo');
  if (!logo) return;

  const bg = [...logo.querySelectorAll('.header-logo_bg')].find(el => getComputedStyle(el)
    .display !== 'none');
  if (!bg) return;

  const state = { speed: 30 };
  let lastDir = 1;
  let returnTimer;
  let deg = 0;
  let userScrolled = false;

  window.addEventListener('wheel', () => { userScrolled = true; }, { once: true });
  window.addEventListener('touchmove', () => { userScrolled = true; }, { once: true });

  gsap.ticker.add((time, deltaTime) => {
    const dt = Math.min(deltaTime, 100);
    deg += state.speed * (dt / 1000);
    gsap.set(bg, { rotation: deg, transformOrigin: 'center center' });
  });

  lenis.on('scroll', ({ velocity }) => {
    if (!userScrolled) return;

    if (velocity !== 0) lastDir = velocity > 0 ? 1 : -1;

    const speed = lastDir * (30 + Math.abs(velocity) * 10);
    gsap.to(state, { speed, duration: 0.3, ease: 'Out', overwrite: true });

    clearTimeout(returnTimer);
    returnTimer = setTimeout(() => {
      gsap.to(state, { speed: lastDir * 30, duration: durL, ease: 'Out' });
    }, 100);
  });
}

function initScrollBar() {
  gsap.matchMedia().add(`(min-width: ${breakPoint}px)`, () => {

    const bar = document.querySelector('[data-s-bar]');
    if (!bar) return;

    const thumb = bar.querySelector('[data-s-bar-thumb]');
    const label = bar.querySelector('[data-s-bar-label]');

    ScrollTrigger.create({
      start: 'top top',
      end: 'bottom bottom',
      onUpdate: self => {
        const progress = Math.round(self.progress * 100);
        bar.style.setProperty('--progress', `${self.progress * 100}%`);
        if (label) label.textContent = `${String(progress).padStart(2, '0')}`;
      }
    });

    let dragging = false;

    thumb.addEventListener('pointerenter', () => { document.body.style.cursor = 'grab'; });
    thumb.addEventListener('pointerleave', () => {
      if (!dragging) document.body.style.cursor =
        '';
    });

    thumb.addEventListener('pointerdown', e => {
      dragging = true;
      thumb.setPointerCapture(e.pointerId);
      document.body.style.cursor = 'grabbing';
    });

    thumb.addEventListener('pointermove', e => {
      if (!dragging) return;

      const rect = bar.getBoundingClientRect();
      const progress = Math.max(0, Math.min(1, (e.clientY - rect.top) / rect.height));
      const maxScroll = document.documentElement.scrollHeight - window.innerHeight;

      lenis.scrollTo(progress * maxScroll, { duration: 3.2 });
    });

    thumb.addEventListener('pointerup', () => {
      dragging = false;
      document.body.style.cursor = 'grab';
    });

  });
}

function initTFTLjson() {

  document.querySelectorAll('.credits').forEach(trigger => {
    const lottieEl = trigger.querySelector('.credits_logo');
    if (!lottieEl) return;

    const anim = lottie.loadAnimation({
      container: lottieEl,
      renderer: 'svg',
      loop: false,
      autoplay: false,
      path: lottieEl.getAttribute('data-json')
    });

    anim.goToAndStop(0, true);

    const totalFrames = 99;
    const tl = gsap.timeline({ paused: true });

    tl.to({ p: 0 }, {
      p: 1,
      duration: 1,
      ease: "none",
      onUpdate: function () {
        const frame = Math.round(this.targets()[0].p * (totalFrames - 1));
        anim.goToAndStop(frame, true);
      }
    });

    trigger.addEventListener('mouseenter', () => {
      gsap.to(tl, { progress: 0.5, duration: 1 });
    });

    trigger.addEventListener('mouseleave', () => {
      gsap.to(tl, { progress: 1, duration: 1 });
    });
  });

}

// Cards

function initCardParts() {
  document.querySelectorAll('[hover-card]').forEach(card => {
    const info = card.querySelector('[hover="info"]');

    const headlines = card.querySelectorAll('[hover="h"]');
    const paragraphs = card.querySelectorAll('[hover="p"]');
    const lines = card.querySelectorAll('[hover="line"]');

    animateTextH(headlines, 'initial');
    animateTextP(paragraphs, 'initial');
    animateLine(lines, 'initial');

    function playForward() {
      animateTextH(headlines, 'reveal', 0);
      animateTextP(paragraphs, 'reveal', 0);
      animateLine(lines, 'reveal', 0);
    }

    function playReverse() {
      animateTextH(headlines, 'hide', 0);
      animateTextP(paragraphs, 'hide', 0);
      animateLine(lines, 'hide', 0);
    }

    card.addEventListener('mouseenter', playForward);
    card.addEventListener('mouseleave', playReverse);
  });
}

function initAccordion() {
  let currentlyOpen = null;

  document.querySelectorAll('[data-accordion-card]').forEach(card => {
    const content = card.querySelector(`[data-accordion-card="content"]`);
    const plus = card.querySelector(`[data-ico-plus]`);
    const paragraphs = card.querySelectorAll(`[data-accordion-card="p"]`);
    const ctns = card.querySelectorAll(`[data-accordion-card="ctn"]`);
    if (!content) return;

    gsap.set(content, { height: 0, overflow: 'hidden' })

    function open() {
      card.classList.add('is-active');

      gsap.to(content, {
        height: 'auto',
        duration: durL,
        ease: 'Out',
        onComplete: () => {
          ScrollTrigger.refresh();
        }
      })

      gsap.fromTo(plus, { rotate: 0 }, {
        rotate: -45,
        duration: durM,
        ease: 'InOut',
        overwrite: true
      })

      animateTextP(paragraphs, 'reveal')
      animateCtn(ctns, 'reveal')
    }

    function close() {
      card.classList.remove('is-active');

      gsap.to(content, {
        height: 0,
        duration: durL,
        ease: 'Out',
        onComplete: () => {
          ScrollTrigger.refresh();
        },
        overwrite: true
      })

      gsap.to(plus, {
        rotate: -90,
        duration: durM,
        ease: 'InOut',
        overwrite: true
      })

      animateTextP(paragraphs, 'hide', 0)
      animateCtn(ctns, 'hide', 0)
    }

    card.addEventListener("click", () => {
      if (currentlyOpen && currentlyOpen !== card) {
        currentlyOpen.closeFunc();
      }

      if (currentlyOpen !== card) {
        open();
        currentlyOpen = card;
      } else {
        close();
        currentlyOpen = null;
      }
    });

    card.closeFunc = close;
  });

  ScrollTrigger.refresh();
}

// Sliders

function initSlider() {
  const sliders = gsap.utils.toArray('[data-slider]')
  if (!sliders.length) return

  sliders.forEach(root => {
    const slider = {
      $slides: root.querySelectorAll('[data-slider="slide"]'),
      $pag: root.querySelector('[data-slider="pag"]'),
      $prev: root.querySelector('[data-slider="prev"]'),
      $next: root.querySelector('[data-slider="next"]'),
      $current: root.querySelector('[data-slider="current"]'),
      $total: root.querySelector('[data-slider="total"]'),
      $next_num: root.querySelector('[data-slider="next-num"]'),
      $progressEl: root.querySelector('[data-slider="progress"]'),
      current: 0,
      prev: null,
      animating: false,
      autoDuration: 6
    }

    slider.length = slider.$slides.length
    if (!slider.length) return

    if (slider.length === 1) {
      slider.$pag.style.display = 'none'
      return
    }

    gsap.set(slider.$slides, { display: 'none', position: 'absolute' })
    gsap.set(slider.$slides[slider.current], { display: 'block', position: 'relative' })

    function walk() {
      const prevSlide = slider.$slides[slider.prev];
      const prevH = prevSlide.querySelectorAll('[data-slider="h"]');
      const prevP = prevSlide.querySelectorAll('[data-slider="p"]');
      const prevCtn = prevSlide.querySelectorAll('[data-slider="ctn"]');
      const prevImg = prevSlide.querySelectorAll('[data-slider="img"]');

      const currSlide = slider.$slides[slider.current];
      const currH = currSlide.querySelectorAll('[data-slider="h"]');
      const currP = currSlide.querySelectorAll('[data-slider="p"]');
      const currCtn = currSlide.querySelectorAll('[data-slider="ctn"]');
      const currImg = currSlide.querySelectorAll('[data-slider="img"]');

      prevSlide.style.zIndex = 0;
      currSlide.style.zIndex = 1;
      gsap.killTweensOf([prevSlide, currSlide]);

      gsap.timeline({
          onComplete: () => {
            prevSlide.style.zIndex = 'auto';
            currSlide.style.zIndex = 1;
            slider.animating = false;
          }
        })
        .set(currSlide, {
          display: 'block',
          position: 'relative'
        })
        .set(prevSlide, {
          display: 'block',
          position: 'absolute'
        })
        .add(() => {
          animateTextH(currH, 'initial');
          animateTextP(currP, 'initial');
          animateCtn(currCtn, 'initial');
          animateSlide(currImg, 'initial');
        })
        .add(() => {
          ScrollTrigger.refresh();
        })
        .add(() => {
          animateTextH(prevH, 'hide', 0);
          animateTextP(prevP, 'hide', 0);
          animateCtn(prevCtn, 'hide', 0);
          animateSlide(prevImg, 'hide', 0);
          animateSlide(currImg, 'reveal', 0);
        })
        .to({}, { duration: durM })
        .add(() => {
          animateTextH(currH, 'reveal', 0);
          animateTextP(currP, 'reveal', 0);
          animateCtn(currCtn, 'reveal', durS);
        })
        .to({}, { duration: durS })
        .set(prevSlide, {
          display: 'none'
        });

    }

    function updateCounter() {
      if (slider.$current) slider.$current.textContent = slider.current + 1
      if (slider.$total) slider.$total.textContent = slider.length
      if (slider.$next_num) {
        slider.$next_num.textContent = slider.current === slider.length - 1 ? 1 : slider
          .current + 2
      }
    }

    function goNext() {
      slider.animating = true
      slider.prev = slider.current
      slider.current = slider.current === slider.length - 1 ? 0 : slider.current + 1
      updateCounter()
      walk()
    }

    function startProgress() {
      if (!slider.$progressEl) return
      gsap.fromTo(slider.$progressEl, { width: '0%' }, {
        width: '100%',
        duration: slider.autoDuration,
        ease: 'none'
      })
    }

    function stopProgress() {
      if (!slider.$progressEl) return
      gsap.killTweensOf(slider.$progressEl)
      gsap.set(slider.$progressEl, { width: '0%' })
    }

    function startAuto() {
      startProgress()
      return setInterval(() => {
        goNext()
        startProgress()
      }, slider.autoDuration * 1000)
    }

    function stopAuto() {
      clearInterval(autoTimer)
      stopProgress()
    }

    updateCounter()

    let autoTimer

    const observer = new IntersectionObserver(([entry]) => {
      if (entry.isIntersecting) {
        stopAuto()
        autoTimer = startAuto()
      } else {
        stopAuto()
      }
    }, { threshold: 0.2 })

    observer.observe(root)

    document.addEventListener('visibilitychange', () => {
      if (document.hidden) {
        stopAuto()
      } else {
        stopAuto()
        autoTimer = startAuto()
      }
    })

    slider.$prev.addEventListener('click', () => {
      if (slider.animating) return
      slider.animating = true
      slider.prev = slider.current
      slider.current = slider.current === 0 ? slider.length - 1 : slider.current - 1
      updateCounter()
      walk()
      stopAuto()
      autoTimer = startAuto()
    })

    slider.$next.addEventListener('click', () => {
      if (slider.animating) return
      stopAuto()
      autoTimer = startAuto()
      goNext()
    })
  })
}

function initCarousel() {
  document.querySelectorAll('[data-carousel]').forEach(slider => {
    const swiperEl = slider.querySelector('.swiper');
    if (!swiperEl) return;

    const progressEl = slider.querySelector('[data-slider="progress"]');
    const currentEl = slider.querySelector('[data-slider="current"]');
    const totalEl = slider.querySelector('[data-slider="total"]');

    const swiper = new Swiper(swiperEl, {
      direction: 'horizontal',
      freeMode: {
        enabled: true,
        momentum: true,
        momentumRatio: 1,
        momentumBounce: true,
        momentumBounceRatio: 1,
        sticky: false
      },
      a11y: {
        enabled: false
      },
      slidesPerView: 'auto',
      grabCursor: true,
      mousewheel: { forceToAxis: true },
      navigation: {
        nextEl: slider.querySelector('[data-slider="next"]'),
        prevEl: slider.querySelector('[data-slider="prev"]')
      },
      speed: 800,
      on: {
        progress(swiper, progress) {
          if (progressEl) progressEl.style.width = `${progress * 100}%`;
        },
        slideChange(swiper) {
          if (currentEl) currentEl.textContent = swiper.realIndex + 1;
        },
        afterInit(swiper) {
          if (currentEl) currentEl.textContent = 1;
          if (totalEl) totalEl.textContent = swiper.slides.length;
        }
      }
    });
  });
}

function initLightbox() {
  const items = Array.from(document.querySelectorAll('[data-lightbox]')).filter(el => el
    .offsetParent !== null);

  if (!items.length) return;

  const lightbox = document.querySelector('[data-lightbox-modal]');
  const img = lightbox.querySelector('[data-lightbox-img]');
  const btnClose = lightbox.querySelector('[data-slider="close"]');
  const btnPrev = lightbox.querySelector('[data-slider="prev"]');
  const btnNext = lightbox.querySelector('[data-slider="next"]');
  const elCurrent = lightbox.querySelector('[data-slider="current"]');
  const elTotal = lightbox.querySelector('[data-slider="total"]');
  const elProgress = lightbox.querySelector('[data-slider="progress"]');

  let current = 0;
  const srcs = Array.from(items).map(el => el.src || el.dataset.src);
  gsap.set(lightbox, { display: 'none' });

  function updateCounter() {
    if (elCurrent) elCurrent.textContent = String(current + 1).padStart(2, '0');
    if (elTotal) elTotal.textContent = String(srcs.length).padStart(2, '0');
    if (elProgress) gsap.to(elProgress, {
      width: `${(current + 1) / srcs.length * 100}%`,
      duration: durS,
      ease: 'Out'
    });
  }

  function open(index) {
    current = index;
    img.src = srcs[current];
    updateCounter();

    gsap.set(lightbox, { display: 'block' });
    gsap.fromTo(lightbox, { opacity: 0 }, {
      opacity: 1,
      duration: durM,
      ease: 'Out'
    });
    gsap.fromTo(img, { opacity: 0, scale: 0.5 }, {
      opacity: 1,
      scale: 1,
      duration: durM,
      ease: 'Out'
    });

    lockScroll();
  }

  function close() {
    gsap.to(lightbox, {
      opacity: 0,
      duration: durS,
      ease: 'In',
      onComplete: () => {
        gsap.set(lightbox, { display: 'none' });
      }
    });

    unlockScroll();
  }

  function slide(direction) {
    const outX = direction === 1 ? -125 : 125;
    const inX = direction === 1 ? 125 : -125;

    gsap.to(img, {
      xPercent: outX,
      duration: durS,
      ease: 'In',
      onComplete: () => {
        current = (current + direction + srcs.length) % srcs.length;
        img.src = srcs[current];
        updateCounter();
        gsap.fromTo(img, { xPercent: inX }, { xPercent: 0, duration: durM, ease: 'Out' });
      }
    });
  }

  document.querySelectorAll('[data-lightbox-btn]').forEach(trigger => {
    trigger.addEventListener('click', () => open(Number(trigger.dataset.lightboxBtn)));
  });

  items.forEach((el, i) => el.addEventListener('click', () => open(i)));
  btnClose.addEventListener('click', close);
  btnPrev.addEventListener('click', () => slide(-1));
  btnNext.addEventListener('click', () => slide(1));

  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') close();
    if (e.key === 'ArrowLeft') slide(-1);
    if (e.key === 'ArrowRight') slide(1);
  });
}

function initImageZoom() {
  const wrapper = document.querySelector('[data-lightbox-content]');
  if (!wrapper) return;

  const img = wrapper.querySelector('[data-lightbox-img]');
  if (!img) return;

  const pag = wrapper.parentElement?.querySelector('.modal_lightbox_pag');
  const closeBtn = wrapper.parentElement?.querySelector('.modal_close');
  const decor = document.querySelector('.modal_decor');

  function hideUI() {
    if (pag) gsap.to(pag, { yPercent: 100, duration: durM, ease: 'Out' });
    if (closeBtn) gsap.to(closeBtn, { xPercent: 250, duration: durM, ease: 'Out' });
    if (decor) gsap.to(decor, { scale: 1.1, duration: durM, ease: 'Out' });
  }

  function showUI() {
    if (pag) gsap.to(pag, { yPercent: 0, duration: durM, ease: 'Out' });
    if (closeBtn) gsap.to(closeBtn, { xPercent: 0, duration: durM, ease: 'Out' });
    if (decor) gsap.to(decor, { scale: 1, duration: durM, ease: 'Out' });
  }

  // Desktop zoom
  if (window.innerWidth > breakPoint) {
    let isZoomed = false;
    let overflow = 0;
    let targetY = 0;
    let currentY = 0;

    function onTick() {
      currentY += (targetY - currentY) * 0.08;
      gsap.set(img, { y: currentY });
    }

    function onMouseMove(e) {
      if (!isZoomed || overflow <= 0) return;
      const ratio = e.clientY / window.innerHeight;
      targetY = overflow * (1 - 2 * ratio);
    }

    img.style.cursor = 'zoom-in';

    function open() {
      isZoomed = true;
      const scale = window.innerWidth / img.offsetWidth;
      const scaledHeight = img.offsetHeight * scale;
      overflow = Math.max(0, (scaledHeight - window.innerHeight) / 2);
      currentY = 0;
      targetY = 0;

      gsap.to(img, { scale, duration: durM, ease: 'Out' });
      gsap.ticker.add(onTick);
      document.addEventListener('mousemove', onMouseMove);

      hideUI();
      img.style.cursor = 'zoom-out';
    }

    function close() {
      isZoomed = false;
      gsap.ticker.remove(onTick);
      document.removeEventListener('mousemove', onMouseMove);
      targetY = 0;

      gsap.to(img, { scale: 1, y: 0, duration: durM, ease: 'Out' });

      showUI();
      img.style.cursor = 'zoom-in';
    }

    img.addEventListener('click', () => isZoomed ? close() : open());

    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') close();
      if (e.key === 'ArrowLeft') close();
      if (e.key === 'ArrowRight') close();
    });

    return;
  }

  // Mobile pinch-to-zoom
  if (window.innerWidth >= breakPoint) return;

  let scale = 1;
  let startScale = 1;
  let startDist = 0;
  let translateX = 0;
  let translateY = 0;
  let startX = 0;
  let startY = 0;
  let midX = 0;
  let midY = 0;
  let lastTap = 0;

  img.style.touchAction = 'none';

  function getDist(t1, t2) {
    const dx = t1.clientX - t2.clientX;
    const dy = t1.clientY - t2.clientY;
    return Math.sqrt(dx * dx + dy * dy);
  }

  function getMid(t1, t2) {
    return {
      x: (t1.clientX + t2.clientX) / 2,
      y: (t1.clientY + t2.clientY) / 2
    };
  }

  function applyTransform() {
    gsap.set(img, { scale, x: translateX, y: translateY });
  }

  function clampTranslate() {
    const rect = img.getBoundingClientRect();
    const wrapRect = wrapper.getBoundingClientRect();

    const overflowX = Math.max(0, (rect.width - wrapRect.width) / 2);
    const overflowY = Math.max(0, (rect.height - wrapRect.height) / 2);

    const clampedX = Math.max(-overflowX, Math.min(overflowX, translateX));
    const clampedY = Math.max(-overflowY, Math.min(overflowY, translateY));

    if (clampedX !== translateX || clampedY !== translateY) {
      translateX = clampedX;
      translateY = clampedY;
      gsap.to(img, { x: translateX, y: translateY, duration: durS, ease: 'Out' });
    }
  }

  function resetZoom() {
    scale = 1;
    translateX = 0;
    translateY = 0;
    gsap.to(img, { scale: 1, x: 0, y: 0, duration: durM, ease: 'Out' });
    showUI();
  }

  function zoomCenter() {
    scale = 2.5;
    translateX = 0;
    translateY = 0;
    gsap.to(img, { scale, x: 0, y: 0, duration: durM, ease: 'Out' });
    hideUI();
  }

  img.addEventListener('touchstart', (e) => {
    if (e.touches.length === 2) {
      e.preventDefault();
      startDist = getDist(e.touches[0], e.touches[1]);
      startScale = scale;
      const mid = getMid(e.touches[0], e.touches[1]);
      midX = mid.x;
      midY = mid.y;
      startX = translateX;
      startY = translateY;

      if (startScale <= 1) hideUI();
    } else if (e.touches.length === 1) {
      const now = Date.now();
      if (now - lastTap < 300) {
        e.preventDefault();
        scale > 1 ? resetZoom() : zoomCenter();
        lastTap = 0;
        return;
      }
      lastTap = now;

      if (scale > 1) {
        e.preventDefault();
        midX = e.touches[0].clientX;
        midY = e.touches[0].clientY;
        startX = translateX;
        startY = translateY;
      }
    }
  }, { passive: false });

  img.addEventListener('touchmove', (e) => {
    if (e.touches.length === 2) {
      e.preventDefault();
      const dist = getDist(e.touches[0], e.touches[1]);
      const mid = getMid(e.touches[0], e.touches[1]);

      scale = Math.max(1, Math.min(startScale * (dist / startDist), 5));
      translateX = startX + (mid.x - midX);
      translateY = startY + (mid.y - midY);
      applyTransform();
    } else if (e.touches.length === 1 && scale > 1) {
      e.preventDefault();
      translateX = startX + (e.touches[0].clientX - midX);
      translateY = startY + (e.touches[0].clientY - midY);
      applyTransform();
    }
  }, { passive: false });

  img.addEventListener('touchend', (e) => {
    if (e.touches.length === 0) {
      if (scale <= 1.05) {
        resetZoom();
      } else {
        clampTranslate();
      }
    }
  });
}

// Tabs

function initTabs() {
  const tabsComponents = document.querySelectorAll('[data-tabs]');
  if (!tabsComponents.length) return;

  tabsComponents.forEach(component => {
    const triggers = [...component.querySelectorAll('[data-tab-trigger]')];
    const contents = component.querySelectorAll('[data-tab-content]');
    let activeIndex = 0;
    let isAnimating = false;

    triggers[0].classList.add('is-active');
    contents[0].classList.add('is-active');

    triggers.forEach((trigger, newIndex) => {
      trigger.addEventListener('click', () => {
        if (newIndex === activeIndex || isAnimating) return;

        const oldTrigger = triggers[activeIndex];
        const oldContent = component.querySelector(
          `[data-tab-content="${oldTrigger.getAttribute('data-tab-trigger')}"]`);
        const oldH = oldContent.querySelectorAll('[data-tab="h"]');
        const oldP = oldContent.querySelectorAll('[data-tab="p"]');
        const oldCtn = oldContent.querySelectorAll('[data-tab="ctn"]');
        const oldSlide = oldContent.querySelectorAll('[data-tab="slide"]');

        const newContent = component.querySelector(
          `[data-tab-content="${trigger.getAttribute('data-tab-trigger')}"]`);
        const newH = newContent.querySelectorAll('[data-tab="h"]');
        const newP = newContent.querySelectorAll('[data-tab="p"]');
        const newCtn = newContent.querySelectorAll('[data-tab="ctn"]');
        const newSlide = newContent.querySelectorAll('[data-tab="slide"]');

        gsap.killTweensOf([oldContent, newContent]);
        isAnimating = true;

        gsap.timeline({
            onComplete: () => {
              isAnimating = false;
            }
          })
          .set(newContent, {
            display: 'block',
            position: 'relative',
            zIndex: 1
          })
          .set(oldContent, {
            display: 'block',
            position: 'absolute',
            zIndex: 0
          })
          .add(() => {
            animateTextH(newH, 'initial');
            animateTextP(newP, 'initial');
            animateCtn(newCtn, 'initial');
            animateSlide(newSlide, 'initial');
          })
          .add(() => {
            ScrollTrigger.refresh();
          })
          .add(() => {
            animateTextH(oldH, 'hide', 0);
            animateTextP(oldP, 'hide', 0);
            animateCtn(oldCtn, 'hide', 0);
            animateSlide(oldSlide, 'hide', 0);
            animateSlide(newSlide, 'reveal', 0);
          })
          .to({}, { duration: durM })
          .add(() => {
            animateTextH(newH, 'reveal', 0);
            animateTextP(newP, 'reveal', 0);
            animateCtn(newCtn, 'reveal', durS);
          })
          .to({}, { duration: durS })
          .set(oldContent, {
            display: 'none'
          });

        oldTrigger.classList.remove('is-active');
        trigger.classList.add('is-active');
        activeIndex = newIndex;
      });
    });
  });
}

function initTabsHero() {
  const component = document.querySelector('[data-tabs-hero]');
  if (!component) return;

  const triggers = [...component.querySelectorAll('[data-tab-trigger]')];
  const hilight = component.querySelector('.hero-s_tabs_divider');
  let activeIndex = 0;
  let isAnimating = false;

  triggers[0].classList.add('is-active');

  function updateHilight() {
    const activeTab = component.querySelector('[data-tab-trigger].is-active');
    if (!activeTab) return;

    hilight.className = hilight.className.replace(/\bis-\S+/g, '').trim();
    hilight.classList.add(`is-${activeTab.getAttribute('data-tab-trigger')}`);
  }

  updateHilight();

  triggers.forEach((trigger, newIndex) => {
    trigger.addEventListener('click', () => {
      if (newIndex === activeIndex || isAnimating) return;

      const oldTrigger = triggers[activeIndex];
      const oldContent = component.querySelector(
        `[data-tab-content="${oldTrigger.getAttribute('data-tab-trigger')}"]`);

      const newContent = component.querySelector(
        `[data-tab-content="${trigger.getAttribute('data-tab-trigger')}"]`);
      const newImg = newContent.querySelector('[data-tab="img"]');

      gsap.killTweensOf([oldContent, newContent]);
      isAnimating = true;

      gsap.timeline({
          onComplete: () => {
            isAnimating = false;
          }
        })
        .set(newContent, {
          display: 'block',
          position: 'relative',
          zIndex: 1
        })
        .set(oldContent, {
          display: 'block',
          position: 'absolute',
          zIndex: 0
        })
        .add(() => {
          ScrollTrigger.refresh();
        })
        .fromTo(newImg, {
          opacity: 0,
        }, {
          opacity: 1,
          duration: durM,
          ease: 'InOut',
          overwrite: true
        })
        .set(oldContent, {
          display: 'none'
        });

      oldTrigger.classList.remove('is-active');
      trigger.classList.add('is-active');
      activeIndex = newIndex;
      updateHilight();
    });
  });
}

function initTabsHilight() {
  const tabsWrappers = document.querySelectorAll('[data-tabs-hilight]');
  if (!tabsWrappers.length) return;

  tabsWrappers.forEach(wrapper => {
    const tabs = wrapper.querySelectorAll('[data-tab]');
    const hilight = wrapper.querySelector('[data-tab-hilight]');
    if (!tabs.length || !hilight) return;

    const isHorizontal = wrapper.dataset.tabsHilight === 'hor';

    function updateHilight() {
      setTimeout(() => {
        const activeTab = wrapper.querySelector('[data-tab].is-active');
        if (!activeTab) return;

        gsap.to(hilight, {
          ...(isHorizontal ? { x: activeTab.offsetLeft, width: activeTab.offsetWidth } :
          { y: activeTab.offsetTop, height: activeTab.offsetHeight }),
          duration: durM,
          ease: 'InOut'
        });
      }, 40);
    }

    updateHilight();

    tabs.forEach(tab => {
      tab.addEventListener('click', () => updateHilight());
    });
  });
}

// Modals

function initModalCta() {
  document.querySelectorAll('[data-modal-cta-btn]').forEach(btn => {
    const id = btn.getAttribute('data-modal-cta-btn');
    const popup = document.querySelector(`[data-modal-cta="${id}"]`);
    if (!popup) return;

    const container = popup.querySelector('[data-modal-container]');
    const overlay = popup.querySelector('[data-modal-over]');
    const closeBtns = popup.querySelectorAll('[data-modal-close]');

    let isOpen = false;

    gsap.set(popup, { display: 'none' });
    gsap.set(container, { transformPerspective: 1000 });

    function open() {
      gsap.set([popup, overlay], { display: 'block' });

      gsap.fromTo(container, {
        scale: 0,
        rotateX: -90,
        yPercent: -100,
        rotate: -25
      }, {
        scale: 1,
        rotateX: 0,
        yPercent: 0,
        rotate: 0,
        duration: durL,
        ease: 'Out',
        overwrite: true
      });

      gsap.fromTo(overlay, { opacity: 0 }, {
        opacity: 1,
        duration: durL,
        ease: 'Out',
        overwrite: true
      });

      lockScroll();
    }

    function close() {
      const isMobile = window.innerWidth < breakPoint;

      gsap.to(container, {
        scale: 1,
        rotateX: 90,
        yPercent: 200,
        rotate: 25,
        duration: durM,
        ease: 'In',
        onComplete: () => {
          gsap.set([popup, overlay], { display: 'none' })
        },
        overwrite: true
      });

      gsap.to(overlay, {
        opacity: 0,
        duration: durM,
        ease: 'In',
        overwrite: true
      });

      unlockScroll();
    }

    btn.addEventListener("click", () => {
      if (!isOpen) {
        open();
        isOpen = true;
      }
    });

    closeBtns.forEach(closeBtn => {
      closeBtn.addEventListener("click", () => {
        if (isOpen) {
          close();
          isOpen = false;
        }
      });
    });

    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        if (isOpen) {
          close();
          isOpen = false;
        }
      }
    });
  });
}

function initModalMenu() {
  document.querySelectorAll('[data-modal-menu-btn]').forEach(btn => {
    const id = btn.getAttribute('data-modal-menu-btn');
    const popup = document.querySelector(`[data-modal-menu="${id}"]`);
    if (!popup) return;

    const container = popup.querySelector('[data-modal-container]');
    const overlay = popup.querySelector('[data-modal-over]');
    const closeBtns = document.querySelectorAll(`[data-modal-close="${id}"]`);

    const accents = popup.querySelectorAll('[data-part="a"]');
    const headlines = popup.querySelectorAll('[data-part="h"]');
    const paragraphs = popup.querySelectorAll('[data-part="p"]');
    const ctns = popup.querySelectorAll('[data-part="ctn"]');

    const menuLabel = btn.querySelectorAll('.btn-menu_label');
    const ico1 = btn.querySelector('[data-ico-menu="is-1"]');
    const ico2 = btn.querySelector('[data-ico-menu="is-2"]');

    const themedElements = document.querySelectorAll('[data-theme]');

    let isOpen = false;

    gsap.set(popup, { display: 'none' });
    gsap.set([ico1, ico2], { rotate: 180 });

    function open() {
      gsap.set([popup, overlay], { display: 'block' });
      themedElements.forEach(el => {
        if (!el.classList.contains('theme_on-dark')) {
          el.classList.add('theme_on-dark');
          el.setAttribute('data-modal-themed', '');
        }
      });
      menuLabel.forEach(el => el.classList.toggle('is-active'));

      gsap.fromTo(container, { yPercent: 0 }, {
        yPercent: 0,
        duration: durL,
        ease: 'Out',
        overwrite: true
      });

      gsap.to(ico1, {
        rotate: -45,
        duration: durM,
        ease: 'InOut',
        overwrite: true
      });
      gsap.to(ico2, {
        rotate: 45,
        duration: durM,
        ease: 'InOut',
        overwrite: true
      });

      gsap.fromTo(overlay, { opacity: 0 }, {
        opacity: 1,
        duration: durM,
        ease: 'Out',
        overwrite: true
      });

      animateTextA(accents, 'reveal');
      animateTextH(headlines, 'reveal');
      animateTextP(paragraphs, 'reveal');
      animateCtn(ctns, 'reveal');

      lockScroll();
    }

    function close() {
      themedElements.forEach(el => {
        if (el.hasAttribute('data-modal-themed')) {
          el.classList.remove('theme_on-dark');
          el.removeAttribute('data-modal-themed');
        }
      });
      menuLabel.forEach(el => el.classList.toggle('is-active'));

      gsap.to(container, {
        yPercent: 0,
        duration: durM,
        ease: 'In',
        onComplete: () => {
          gsap.set([popup, overlay], { display: 'none' })
        },
        overwrite: true
      });

      gsap.to(ico1, {
        rotate: 180,
        duration: durM,
        ease: 'InOut',
        overwrite: true
      });
      gsap.to(ico2, {
        rotate: 180,
        duration: durM,
        ease: 'InOut',
        overwrite: true
      });

      gsap.to(overlay, {
        opacity: 0,
        duration: durM,
        ease: 'In',
        overwrite: true
      });

      animateTextA(accents, 'hide');
      animateTextH(headlines, 'hide');
      animateTextP(paragraphs, 'hide');
      animateCtn(ctns, 'hide');

      unlockScroll();
    }

    btn.addEventListener("click", () => {
      if (!isOpen) {
        open();
        isOpen = true;
      } else {
        close();
        isOpen = false;
      }
    });

    closeBtns.forEach(closeBtn => {
      closeBtn.addEventListener("click", () => {
        if (isOpen) {
          close();
          isOpen = false;
        }
      });
    });

    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        if (isOpen) {
          close();
          isOpen = false;
        }
      }
    });
  });
}

