// Floating tips

function initFloatingTips() {
  gsap.matchMedia().add(`(min-width: ${breakPoint}px)`, () => {

    const cursorMap = new Map(
      [...document.querySelectorAll('[floating-tip]')].map(el => [el.getAttribute(
        'floating-tip'), el])
    );
    const activeCursors = new Set();

    function checkBounds(cursor, x, y) {
      const rect = cursor.getBoundingClientRect();
      cursor.classList.toggle('is-left', x + rect.width > window.innerWidth);
      cursor.classList.toggle('is-top', y + rect.height > window.innerHeight);
    }

    document.addEventListener('mousemove', e => {
      activeCursors.forEach(cursor => {
        checkBounds(cursor, e.clientX, e.clientY);
        gsap.to(cursor, {
          x: e.clientX,
          y: e.clientY,
          duration: durL * 2,
          ease: 'power3'
        });
      });
    });

    function show(cursor, x, y) {
      gsap.set(cursor, { x, y });
      checkBounds(cursor, x, y);
      cursor.classList.add('is-active');
      activeCursors.add(cursor);
    }

    function hide(cursor) {
      cursor.classList.remove('is-active', 'is-left', 'is-top');
      activeCursors.delete(cursor);
    }

    document.querySelectorAll('[floating-tip-trigger]').forEach(trigger => {
      const cursor = cursorMap.get(trigger.getAttribute('floating-tip-trigger'));
      if (!cursor) return;

      trigger.addEventListener('mouseenter', e => show(cursor, e.clientX, e.clientY));
      trigger.addEventListener('mouseleave', () => hide(cursor));

      if (trigger.matches(':hover')) show(cursor, 0, 0);
    });

  });
}

// Filter

function initFilter() {
  document.querySelectorAll('[data-filter]').forEach(wrapper => {
    const list = wrapper.querySelector('[data-filter-list]');
    if (!list) return;

    const countEl = wrapper.querySelector('[data-filter-count]');
    const emptyEl = wrapper.querySelector('[data-filter-empty]');
    const filters = {};
    const items = [...list.querySelectorAll('[data-filter-item]')];

    function getVisible() {
      if (!Object.keys(filters).length) return items;
      return items.filter(item =>
        Object.entries(filters).every(([group, value]) => [...item.querySelectorAll(
            `[data-${group}]`)]
          .map(el => el.dataset[group])
          .includes(value)
        )
      );
    }

    function arrange() {
      const visible = getVisible();
      const hidden = items.filter(i => !visible.includes(i));

      hidden.forEach(item => gsap.set(item, { display: 'none' }));
      visible.forEach(item => gsap.set(item, { display: '' }));

      if (emptyEl) {
        if (visible.length === 0) {
          gsap.set(emptyEl, { display: '' });
          gsap.fromTo(emptyEl, { opacity: 0 }, {
            opacity: 1,
            duration: durM,
            ease: 'Out'
          });
        } else {
          gsap.set(emptyEl, { display: 'none' });
        }
      }

      if (countEl) {
        const current = { val: parseInt(countEl.textContent) || 0 };
        gsap.to(current, {
          val: visible.length,
          duration: durM,
          ease: 'Out',
          overwrite: true,
          onUpdate: () => countEl.textContent = Math.round(current.val)
        });
      }

      gsap.fromTo(list, { opacity: 0, y: '10rem' }, {
        opacity: 1,
        y: '0rem',
        duration: durL,
        ease: 'Out',
        clearProps: 'y',
        onComplete: () => ScrollTrigger.refresh()
      });
    }

    function updateUrl() {
      const params = new URLSearchParams(filters);
      const query = params.toString();
      history.replaceState(null, '', query ? `?${query}` : location.pathname);
    }

    arrange();

    wrapper.querySelectorAll('[data-filter-trigger]').forEach(btn => {
      btn.addEventListener('click', () => {
        const group = btn.dataset.filterGroup;
        const value = btn.dataset.filterTrigger;

        wrapper.querySelectorAll(`[data-filter-group="${group}"]`).forEach(b => b
          .classList.remove('is-active'));
        btn.classList.add('is-active');

        if (value === '*') {
          delete filters[group];
        } else {
          filters[group] = value;
        }

        updateUrl();

        gsap.timeline()
          .to(list, {
            opacity: 0,
            duration: durS,
            ease: 'Out',
            overwrite: true
          })
          .add(() => {
            arrange();
          });
      });
    });

    const params = new URLSearchParams(location.search);
    const groups = [...new Set([...wrapper.querySelectorAll('[data-filter-trigger]')].map(b => b
      .dataset.filterGroup))];

    groups.forEach(group => {
      const value = params.get(group);
      const btn = value ?
        wrapper.querySelector(
          `[data-filter-group="${group}"][data-filter-trigger="${value}"]`) :
        wrapper.querySelector(`[data-filter-group="${group}"][data-filter-trigger="*"]`);

      if (btn) btn.click();
    });
  });
}

function initSort() {
  document.querySelectorAll('[data-sort]').forEach(wrapper => {
    const list = wrapper.querySelector('[data-sort-list]');
    if (!list) return;

    const items = [...list.querySelectorAll('[data-sort-item]')];
    let sort = { key: null, order: 'asc' };

    function camel(str) {
      return str.replace(/-([a-z])/g, (_, c) => c.toUpperCase());
    }

    function arrange() {
      const dataKey = camel(`sort-${sort.key}`);

      [...items].sort((a, b) => {
        const aEl = a.querySelector(`[data-sort-${sort.key}]`);
        const bEl = b.querySelector(`[data-sort-${sort.key}]`);
        const aVal = aEl?.dataset[dataKey] ?? '';
        const bVal = bEl?.dataset[dataKey] ?? '';
        const aNum = parseFloat(aVal);
        const bNum = parseFloat(bVal);
        const isNum = !isNaN(aNum) && !isNaN(bNum);
        const cmp = isNum ? aNum - bNum : aVal.localeCompare(bVal);
        return sort.order === 'asc' ? cmp : -cmp;
      }).forEach(item => list.appendChild(item));
    }

    wrapper.querySelectorAll('[data-sort-trigger]').forEach(btn => {
      btn.addEventListener('click', () => {
        if (btn.classList.contains('is-active')) return;

        sort.key = btn.dataset.sortTrigger;
        sort.order = btn.dataset.sortOrder ?? 'asc';

        wrapper.querySelectorAll('[data-sort-trigger]').forEach(b => b.classList.remove(
          'is-active'));
        btn.classList.add('is-active');

        gsap.timeline()
          .to(list, {
            opacity: 0,
            duration: durS,
            ease: 'Out',
            overwrite: true
          })
          .add(() => {
            arrange();
            gsap.fromTo(list, { opacity: 0, y: '10rem' }, {
              opacity: 1,
              y: '0rem',
              duration: durL,
              ease: 'Out',
              clearProps: 'y',
              onComplete: () => ScrollTrigger.refresh()
            });
          });
      });
    });

    const first = wrapper.querySelector('[data-sort-trigger]');
    if (first) first.click();
  });
}

function initReset() {
  const resetBtns = document.querySelectorAll('[data-reset]');
  if (!resetBtns.length) return;

  function update() {
    const filtered = [...document.querySelectorAll(
        '[data-filter-trigger]:not([data-filter-trigger="*"])')]
      .some(b => b.classList.contains('is-active'));

    const sortTriggers = [...document.querySelectorAll('[data-sort-trigger]')];
    const sorted = sortTriggers.length && !sortTriggers[0].classList.contains('is-active');

    resetBtns.forEach(btn => btn.classList.toggle('is-disabled', !filtered && !sorted));
  }

  document.querySelectorAll('[data-filter-trigger], [data-sort-trigger]').forEach(btn => {
    btn.addEventListener('click', update);
  });

  resetBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      if (btn.classList.contains('is-disabled')) return;

      document.querySelectorAll('[data-filter-trigger="*"]').forEach(b => b.click());

      const sortFirst = document.querySelector('[data-sort-trigger]');
      if (sortFirst) sortFirst.click();
    });
  });

  update();
}

// Home flow

function initTranistionFlow() {

  const heroArea = document.querySelector('.hero-scroll-area');

  if (heroArea) {
    const heroS = heroArea.querySelector('.hero-s');

    const isMobile = window.innerWidth < breakPoint;

    const bg = heroArea.querySelector('.hero-w_bg');
    const img = bg.querySelector('.img');

    function onReady() {
      const bgHeight = bg.offsetHeight;

      const tl = gsap.timeline({
        scrollTrigger: {
          trigger: heroArea,
          start: 'top top',
          end: 'bottom bottom',
          scrub: true
        }
      });

      if (!isMobile) {
        tl.fromTo(heroS, { y: 0 }, {
            y: -((bgHeight * 1.25) - window.innerHeight),
            ease: 'Ease',
            duration: 0.6
          })
          .fromTo(bg, { y: 0 }, {
            y: -(bgHeight - window.innerHeight),
            ease: 'Ease',
            duration: 0.6
          }, '<');
      }

      tl.fromTo(bg, { scale: 1, translateZ: 10, transformOrigin: '50% 75%' }, {
        scale: 2,
        translateZ: 10,
        ease: 'In',
        duration: 0.6
      }, isMobile ? '>' : '-=0.2');
    }

    if (img.complete) {
      onReady();
    } else {
      img.addEventListener('load', onReady, { once: true });
    }

  }

  const benefitsIntroS = document.querySelector('.benefits-intro-w');

  if (benefitsIntroS) {
    const title = benefitsIntroS.querySelectorAll('[data-circle-text]');

    gsap.timeline({
        scrollTrigger: {
          trigger: benefitsIntroS,
          start: 'top bottom',
          end: 'bottom top',
          scrub: true
        }
      })
      .fromTo(title, { wordSpacing: '0rem' }, {
        wordSpacing: '10rem',
        ease: 'none'
      });
  }

  const locInfoW = document.querySelector('.loc-info-w');

  if (locInfoW) {

    const locInfoS = locInfoW.querySelector('.loc-info-s');

    const paragraphs = locInfoW.querySelectorAll('[data-part="p"]');
    const ctns = locInfoW.querySelectorAll('[data-part="ctn"]');

    animateTextP(paragraphs, 'initial');
    animateCtn(ctns, 'initial');

    gsap.timeline({
        scrollTrigger: {
          trigger: locInfoW,
          start: 'top 30%',
          end: 'bottom bottom',
          scrub: 0.5,
          onEnter: () => {
            animateTextP(paragraphs, 'reveal', 0.1);
            animateCtn(ctns, 'reveal', 0.1);
          },
          onLeaveBack: () => {
            animateTextP(paragraphs, 'hide', 0);
            animateCtn(ctns, 'hide', 0);
          }
        }
      })
      .fromTo(locInfoS, { opacity: 0, scale: 0.75 }, {
        opacity: 1,
        scale: 1,
        ease: 'none'
      }, 0);
  }

  const locArea = document.querySelector('.loc-scroll-area');

  if (locArea) {
    gsap.matchMedia().add(`(min-width: ${breakPoint}px)`, () => {

      const track = locArea.querySelector('.loc-scroll-area_track');
      const scrollDistance = track.scrollWidth - locArea.offsetWidth;

      locArea.style.height = `${track.scrollWidth}px`;
      ScrollTrigger.refresh();

      const horizontalTween = gsap.to(track, {
        x: -scrollDistance,
        ease: 'horScroll',
        scrollTrigger: {
          trigger: locArea,
          start: '2.5% top',
          end: '97.5% bottom',
          scrub: 0.25
        }
      });

      locArea._horizontalTween = horizontalTween;

      const title = locArea.querySelector('.loc-intro-s_title');
      const titleLines = locArea.querySelectorAll('.loc-intro-s_title_line');

      gsap.fromTo(titleLines, { xPercent: gsap.utils.wrap([-5, 25, -15]) },
      {
        xPercent: gsap.utils.wrap([5, -25, 25]),
        ease: 'none',
        scrollTrigger: {
          trigger: locArea,
          start: 'top top',
          end: 'bottom bottom',
          scrub: 0.25
        }
      });

      const flowerIntro = locArea.querySelector('.flower.loc-intro');

      gsap.fromTo(flowerIntro, { xPercent: 0 },
      {
        xPercent: -25,
        ease: 'none',
        scrollTrigger: {
          trigger: locArea,
          start: 'top top',
          end: 'bottom bottom',
          scrub: 0.25
        }
      });

      const flowerPath = locArea.querySelector('.flower.loc-path');

      gsap.fromTo(flowerPath, { yPercent: 0 },
      {
        yPercent: 25,
        ease: 'none',
        scrollTrigger: {
          trigger: locArea,
          start: 'bottom bottom',
          end: 'bottom top',
          scrub: 0.25
        }
      });
    });
  }

  const path = document.querySelector('.img.loc-path');

  if (path) {
    const horizontalArea = path.closest('[data-scroll-horizontal]');

    gsap.fromTo(path, {
      clipPath: 'inset(0% 100% 0% 0%)'
    }, {
      clipPath: 'inset(0% 0% 0% 0%)',
      duration: durL * 2,
      ease: 'Out',
      delay: durM,
      scrollTrigger: {
        trigger: path,
        containerAnimation: horizontalArea?._horizontalTween,
        start: horizontalArea ? 'left bottom' : 'top bottom',
        once: true
      }
    });
  }

  const mapW = document.querySelector('.loc-w');

  if (mapW) {
    const img = mapW.querySelector('.loc-w_bg_img');

    gsap.from(img, {
      scale: 1.15,
      transformOrigin: 'center bottom',
      ease: 'Ease',
      scrollTrigger: {
        trigger: mapW,
        start: 'top bottom',
        end: 'bottom bottom',
        scrub: 0.25
      }
    });

  }

  const amenArea = document.querySelector('.amen-scroll-area');

  if (amenArea) {
    const amenW = amenArea.querySelector('.amen-w');
    const amenCms = amenArea.querySelector('.amen-cms');

    gsap.timeline({
        scrollTrigger: {
          trigger: amenArea,
          start: 'top top',
          end: 'bottom bottom',
          scrub: true
        }
      })
      .fromTo(amenCms, { scale: 1 }, {
        scale: 2,
        ease: 'In'
      })
      .fromTo(amenW, { opacity: 1 }, {
        opacity: 0,
        ease: 'In'
      }, '<');
  }

  const archArea = document.querySelector('.arch-scroll-area');

  if (archArea) {
    gsap.matchMedia().add(`(min-width: ${breakPoint}px)`, () => {

      const introS = archArea.querySelector('.arch-intro-s');
      const introBgL = introS.querySelector('.arch-intro-s_bg_l');
      const introBgR = introS.querySelector('.arch-intro-s_bg_r');
      const flowerL = introS.querySelector('.flower.arch-intro-l');
      const flowerR = introS.querySelector('.flower.arch-intro-r');

      const archS = archArea.querySelector('.arch-w');
      const archBg = archS.querySelector('.img');
      const archTop = archS.querySelector('.arch-s_t');

      const archTitle = archS.querySelector('[data-text="h"]');
      const archDesc = archS.querySelector('[data-text="p"]');

      gsap.timeline({
          scrollTrigger: {
            trigger: introS,
            start: 'top bottom',
            end: '200% top',
            scrub: true
          }
        })
        // 1 > 2
        .fromTo(introBgL, {
          clipPath: 'polygon(0% 0%, 0% 100%, 44.444% 100%, 44.444% 36.111%, 98.889% 36.111%, 98.889% 99.074%, 44.444% 99.074%, 1.111% 100%, 100% 100%, 100% 0%)',
        }, {
          clipPath: 'polygon(0% 0%, 0% 100%, 44.444% 100%, 44.444% 18.519%, 98.889% 18.519%, 98.889% 81.481%, 44.444% 81.481%, 1.111% 100%, 100% 100%, 100% 0%)',
          ease: 'none',
          duration: 0.5
        })
        .fromTo(introBgR, {
          clipPath: 'polygon(0% 0%, 0% 100%, 1.111% 100%, 1.111% 0.926%, 55.556% 0.926%, 55.556% 63.889%, 1.111% 63.889%, 1.111% 100%, 100% 100%, 100% 0%)',
        }, {
          clipPath: 'polygon(0% 0%, 0% 100%, 1.111% 100%, 1.111% 18.519%, 55.556% 18.519%, 55.556% 81.481%, 1.111% 81.481%, 1.111% 100%, 100% 100%, 100% 0%)',
          ease: 'none',
          duration: 0.5
        }, '<')

        // 2 > 3
        .to(introBgL, {
          clipPath: 'polygon(0% 0%, 0% 100%, 44.444% 100%, 44.444% 18.519%, 100% 18.519%, 100% 81.481%, 44.444% 81.481%, 1.111% 100%, 100% 100%, 100% 0%)',
          ease: 'none',
          duration: 0.1
        })
        .to(introBgR, {
          clipPath: 'polygon(0% 0%, 0% 100%, 0% 100%, 0% 18.519%, 55.556% 18.519%, 55.556% 81.481%, 0% 81.481%, 0% 100%, 100% 100%, 100% 0%)',
          ease: 'none',
          duration: 0.1
        }, '<')
        .fromTo(introS, {
          scale: 1,
        }, {
          scale: 1.84,
          ease: 'InOut',
          duration: 0.4
        })
        .to(flowerL, {
          scale: 1.84,
          xPercent: -50,
          ease: 'InOut',
          duration: 0.4
        }, '<')
        .to(flowerR, {
          scale: 1.84,
          xPercent: 50,
          ease: 'InOut',
          duration: 0.4
        }, '<')
        .fromTo(archS, {
          scale: 0.75,
          transformOrigin: 'center top'
        }, {
          scale: 1,
          ease: 'InOut',
          duration: 0.4
        }, '<');

      animateTextH(archTitle, 'initial');
      animateTextP(archDesc, 'initial');

      ScrollTrigger.create({
        trigger: archArea,
        start: '30% top',
        onEnter: () => {
          animateTextH(archTitle, 'reveal', 0);
          animateTextP(archDesc, 'reveal', durS);
        },
        onLeaveBack: () => {
          animateTextH(archTitle, 'hide', 0);
          animateTextP(archDesc, 'hide', 0);
        }
      });

      gsap.to(archBg, {
        yPercent: 25,
        ease: 'none',
        scrollTrigger: {
          trigger: archArea,
          start: '55% top',
          end: 'bottom top',
          scrub: true
        }
      });

    });
  }

  const footerW = document.querySelector('.footer-w');

  if (footerW) {
    const ClipS = document.querySelector('[data-footer-clip]');
    const footerS = footerW.querySelector('.footer-s');

    const headlines = footerW.querySelectorAll('[data-text="h"]');
    const paragraphs = footerW.querySelectorAll('[data-text="p"]');
    const ctns = footerW.querySelectorAll('[data-text="ctn"]');

    const clipEnd = window.innerWidth >= breakPoint ? 'inset(8% 22% 8% 22%)' :
      'inset(4% 32% 4% 32%)';

    animateTextH(headlines, 'initial');
    animateTextP(paragraphs, 'initial');
    animateCtn(ctns, 'initial');

    gsap.timeline({
        scrollTrigger: {
          trigger: footerW,
          start: 'top 30%',
          end: 'bottom bottom',
          scrub: 0.5,
          onEnter: () => {
            animateTextH(headlines, 'reveal', 0.1);
            animateTextP(paragraphs, 'reveal', 0.1);
            animateCtn(ctns, 'reveal', 0.1);
          },
          onLeaveBack: () => {
            animateTextH(headlines, 'hide', 0);
            animateTextP(paragraphs, 'hide', 0);
            animateCtn(ctns, 'hide', 0);
          }
        }
      })
      .fromTo(ClipS, { clipPath: 'inset(0% 0% 0% 0%)' }, {
        clipPath: clipEnd,
        ease: 'none'
      }, 0)
      .fromTo(footerS, { opacity: 0, scale: 0.75 }, {
        opacity: 1,
        scale: 1,
        ease: 'none'
      }, 0);

    const scrollDown = document.querySelector('.s-down');

    if (scrollDown) {
      gsap.to(scrollDown, {
        opacity: 0,
        ease: 'InOut',
        scrollTrigger: {
          trigger: footerW,
          start: 'top bottom',
          end: 'center bottom',
          scrub: true
        }
      });
    }
  }

  const lotW = document.querySelector('.lot-w');

  if (lotW) {
    const header = lotW.querySelector('.lot-s_info_header');
    const line = lotW.querySelector('.lot-s_info_line');

    ScrollTrigger.create({
      trigger: lotW,
      start: '100px top',
      onEnter: () => {
        header.classList.remove('is-top');
        line.classList.remove('is-top');
      },
      onLeaveBack: () => {
        header.classList.add('is-top');
        line.classList.add('is-top');
      }
    });
  }

}

